package app.cash.kfsm.v2

import app.cash.kfsm.v2.exemplar.DocumentEffect
import app.cash.kfsm.v2.exemplar.DocumentState
import app.cash.kfsm.v2.exemplar.DocumentUpload
import app.cash.kfsm.v2.exemplar.RequestUpload
import app.cash.kfsm.v2.exemplar.ScanReport
import app.cash.kfsm.v2.exemplar.ScanSucceeded
import app.cash.kfsm.v2.exemplar.UploadCompleted
import app.cash.kfsm.v2.testing.InMemoryOutbox
import app.cash.kfsm.v2.testing.InMemoryPendingRequestStore
import io.kotest.core.spec.IsolationMode
import io.kotest.core.spec.style.StringSpec
import io.kotest.matchers.result.shouldBeSuccess
import io.kotest.matchers.shouldBe
import io.kotest.matchers.types.shouldBeInstanceOf

class WorkflowBuilderTest : StringSpec({
    isolationMode = IsolationMode.InstancePerTest

    "workflow builder creates working state machine" {
        val savedValues = mutableListOf<DocumentUpload>()
        val savedOutboxMessages = mutableListOf<OutboxMessage<String, DocumentEffect>>()

        val repository = object : Repository<String, DocumentUpload, DocumentState, DocumentEffect> {
            override fun saveWithOutbox(
                value: DocumentUpload,
                outboxMessages: List<OutboxMessage<String, DocumentEffect>>
            ): Result<DocumentUpload> {
                savedValues.add(value)
                savedOutboxMessages.addAll(outboxMessages)
                return Result.success(value)
            }
        }

        val outbox = InMemoryOutbox<String, DocumentEffect>()
        val pendingStore = InMemoryPendingRequestStore<String, DocumentUpload>()
        val values = mutableMapOf<String, DocumentUpload>()

        val workflow = workflow<String, DocumentUpload, DocumentState, DocumentEffect> {
            repository(repository)
            valueLoader { id -> Result.success(values[id]) }
            outbox(outbox)
            pendingRequestStore(pendingStore)

            settledWhen { state ->
                state is DocumentState.Accepted || state is DocumentState.Rejected
            }

            effects {
                on<DocumentEffect.UploadFile> { id, effect ->
                    EffectOutcome.TransitionProduced(id, UploadCompleted("file-${effect.fileName}"))
                }
                on<DocumentEffect.ScanFile> { id, _ ->
                    EffectOutcome.TransitionProduced(id, ScanSucceeded(ScanReport("checksum", true)))
                }
                on<DocumentEffect.NotifyUser> { _, _ ->
                    EffectOutcome.Completed
                }
            }
        }

        val doc = DocumentUpload(id = "doc-1", state = DocumentState.Idle)
        values["doc-1"] = doc

        val result = workflow.stateMachine.transition(doc, RequestUpload("test.pdf", "content".toByteArray()))

        result.shouldBeSuccess()
        result.getOrThrow().state shouldBe DocumentState.Uploading
        savedValues.size shouldBe 1
        savedOutboxMessages.size shouldBe 1
        savedOutboxMessages[0].effect.shouldBeInstanceOf<DocumentEffect.UploadFile>()
    }

    "workflow builder with settledStates convenience method" {
        val repository = object : Repository<String, DocumentUpload, DocumentState, DocumentEffect> {
            override fun saveWithOutbox(
                value: DocumentUpload,
                outboxMessages: List<OutboxMessage<String, DocumentEffect>>
            ): Result<DocumentUpload> = Result.success(value)
        }

        val workflow = workflow<String, DocumentUpload, DocumentState, DocumentEffect> {
            repository(repository)
            valueLoader { Result.success(null) }
            outbox(InMemoryOutbox())
            pendingRequestStore(InMemoryPendingRequestStore())
            settledStates(DocumentState.Accepted)

            effects {
                on<DocumentEffect.UploadFile> { id, _ ->
                    EffectOutcome.TransitionProduced(id, UploadCompleted("file-id"))
                }
                on<DocumentEffect.ScanFile> { id, _ ->
                    EffectOutcome.TransitionProduced(id, ScanSucceeded(ScanReport("checksum", true)))
                }
                on<DocumentEffect.NotifyUser> { _, _ ->
                    EffectOutcome.Completed
                }
            }
        }

        val doc = DocumentUpload(id = "doc-1", state = DocumentState.Idle)
        val result = workflow.stateMachine.transition(doc, RequestUpload("test.pdf", "content".toByteArray()))

        result.shouldBeSuccess()
    }

    "effect handler builder routes to correct handler" {
        val handledEffects = mutableListOf<String>()

        val handler = EffectHandlerBuilder<String, DocumentUpload, DocumentState, DocumentEffect>().apply {
            on<DocumentEffect.UploadFile> { id, _ ->
                handledEffects.add("upload")
                EffectOutcome.TransitionProduced(id, UploadCompleted("file-id"))
            }
            on<DocumentEffect.ScanFile> { id, _ ->
                handledEffects.add("scan")
                EffectOutcome.TransitionProduced(id, ScanSucceeded(ScanReport("checksum", true)))
            }
            on<DocumentEffect.NotifyUser> { _, _ ->
                handledEffects.add("notify")
                EffectOutcome.Completed
            }
        }.build()

        handler.handle("doc-1", DocumentEffect.UploadFile("test.pdf", byteArrayOf()))
        handler.handle("doc-1", DocumentEffect.ScanFile("file-id"))
        handler.handle("doc-1", DocumentEffect.NotifyUser("doc-1", "Done"))

        handledEffects shouldBe listOf("upload", "scan", "notify")
    }

    "effect handler builder catches exceptions in handlers" {
        val handler = EffectHandlerBuilder<String, DocumentUpload, DocumentState, DocumentEffect>().apply {
            on<DocumentEffect.UploadFile> { _, _ ->
                throw RuntimeException("Upload service unavailable")
            }
            on<DocumentEffect.ScanFile> { id, _ ->
                EffectOutcome.TransitionProduced(id, ScanSucceeded(ScanReport("checksum", true)))
            }
            on<DocumentEffect.NotifyUser> { _, _ ->
                EffectOutcome.Completed
            }
        }.build()

        val result = handler.handle("doc-1", DocumentEffect.UploadFile("test.pdf", byteArrayOf()))

        result.isFailure shouldBe true
        result.exceptionOrNull()?.message shouldBe "Upload service unavailable"
    }

    "ordered effects create messages with dependencies" {
        val savedOutboxMessages = mutableListOf<OutboxMessage<String, DocumentEffect>>()

        val repository = object : Repository<String, DocumentUpload, DocumentState, DocumentEffect> {
            override fun saveWithOutbox(
                value: DocumentUpload,
                outboxMessages: List<OutboxMessage<String, DocumentEffect>>
            ): Result<DocumentUpload> {
                savedOutboxMessages.addAll(outboxMessages)
                return Result.success(value)
            }
        }

        val stateMachine = StateMachine(repository)
        val doc = DocumentUpload(id = "doc-1", state = DocumentState.Idle)

        // Create a transition that uses ordered effects
        val transition = object : Transition<String, DocumentUpload, DocumentState, DocumentEffect>(
            from = setOf(DocumentState.Idle),
            to = DocumentState.Uploading
        ) {
            override fun decide(value: DocumentUpload): Decision<DocumentUpload, DocumentState, DocumentEffect> {
                return Decision.accept(
                    value = value.update(DocumentState.Uploading),
                    Effects.ordered(
                        DocumentEffect.UploadFile("test.pdf", byteArrayOf()),
                        DocumentEffect.NotifyUser(value.id, "Upload started")
                    )
                )
            }
        }

        val result = stateMachine.transition(doc, transition)

        result.shouldBeSuccess()
        savedOutboxMessages.size shouldBe 2

        // First message should have no dependency
        savedOutboxMessages[0].dependsOnEffectId shouldBe null
        savedOutboxMessages[0].effect.shouldBeInstanceOf<DocumentEffect.UploadFile>()

        // Second message should depend on the first
        savedOutboxMessages[1].dependsOnEffectId shouldBe savedOutboxMessages[0].id
        savedOutboxMessages[1].effect.shouldBeInstanceOf<DocumentEffect.NotifyUser>()
    }

    "in-memory outbox respects effect dependencies" {
        val outbox = InMemoryOutbox<String, DocumentEffect>()

        val firstMessage: OutboxMessage<String, DocumentEffect> = OutboxMessage(
            id = "msg-1",
            valueId = "doc-1",
            effect = DocumentEffect.UploadFile("test.pdf", byteArrayOf())
        )
        val secondMessage: OutboxMessage<String, DocumentEffect> = OutboxMessage(
            id = "msg-2",
            valueId = "doc-1",
            effect = DocumentEffect.NotifyUser("doc-1", "Done"),
            dependsOnEffectId = "msg-1"
        )

        outbox.add(firstMessage)
        outbox.add(secondMessage)

        // Initially only the first message should be pending (second is blocked)
        val pending1 = outbox.fetchPending(10).getOrThrow()
        pending1.size shouldBe 1
        pending1[0].id shouldBe "msg-1"

        // After processing the first, the second should become available
        outbox.markProcessed("msg-1")
        val pending2 = outbox.fetchPending(10).getOrThrow()
        pending2.size shouldBe 1
        pending2[0].id shouldBe "msg-2"
    }
})

package app.cash.kfsm.v2.testing

import app.cash.kfsm.v2.PendingRequestStatus
import app.cash.kfsm.v2.PendingRequestStore
import arrow.core.raise.result
import java.util.UUID

/**
 * In-memory implementation of [PendingRequestStore] for testing.
 *
 * Example:
 * ```kotlin
 * val store = InMemoryPendingRequestStore<String, Order>()
 * val awaitable = AwaitableStateMachine(stateMachine, store, settledStates)
 * ```
 */
class InMemoryPendingRequestStore<ID, V> : PendingRequestStore<ID, V> {
    private val requests = mutableMapOf<String, RequestEntry<ID, V>>()

    private data class RequestEntry<ID, V>(
        val valueId: ID,
        var status: PendingRequestStatus<V>
    )

    /**
     * Get all pending request IDs.
     */
    fun allRequestIds(): Set<String> = requests.keys.toSet()

    /**
     * Get the number of pending requests.
     */
    fun size(): Int = requests.size

    /**
     * Check if a request exists.
     */
    fun exists(requestId: String): Boolean = requestId in requests

    /**
     * Clear all requests (for test reset).
     */
    fun clear() {
        requests.clear()
    }

    override fun create(valueId: ID): Result<String> = result {
        val id = "req-${UUID.randomUUID()}"
        requests[id] = RequestEntry(valueId, PendingRequestStatus.Waiting)
        id
    }

    override fun getStatus(requestId: String): Result<PendingRequestStatus<V>> = result {
        requests[requestId]?.status ?: PendingRequestStatus.NotFound
    }

    override fun complete(valueId: ID, value: V): Result<Unit> = result {
        requests.entries
            .filter { it.value.valueId == valueId && it.value.status is PendingRequestStatus.Waiting }
            .forEach { it.value.status = PendingRequestStatus.Completed(value) }
    }

    override fun fail(valueId: ID, error: String): Result<Unit> = result {
        requests.entries
            .filter { it.value.valueId == valueId && it.value.status is PendingRequestStatus.Waiting }
            .forEach { it.value.status = PendingRequestStatus.Failed(error) }
    }

    override fun timeout(requestId: String): Result<Unit> = result {
        requests.remove(requestId)
    }

    override fun delete(requestId: String): Result<Unit> = result {
        requests.remove(requestId)
    }
}

package app.cash.kfsm.v2.exemplar

import app.cash.kfsm.v2.Decision
import app.cash.kfsm.v2.Transition

/**
 * Base class for document upload transitions.
 */
abstract class DocumentTransition(
  from: Set<DocumentState>,
  to: DocumentState
) : Transition<String, DocumentUpload, DocumentState, DocumentEffect>(from, to) {
  constructor(from: DocumentState, to: DocumentState) : this(setOf(from), to)
}

// --- Transitions ---

/**
 * Request to upload a document.
 *
 * Demonstrates Decision.reject: files larger than maxFileSize are rejected
 * without transitioning to a new state.
 */
class RequestUpload(
  private val fileName: String,
  private val fileContent: ByteArray,
  private val maxFileSize: Long = 10 * 1024 * 1024 // 10MB default
) : DocumentTransition(from = DocumentState.Idle, to = DocumentState.Uploading) {

  override fun decide(value: DocumentUpload): Decision<DocumentUpload, DocumentState, DocumentEffect> =
    if (fileContent.size > maxFileSize) {
      Decision.reject("File size ${fileContent.size} exceeds maximum allowed size of $maxFileSize bytes")
    } else {
      Decision.accept(
        value = value.update(DocumentState.Uploading),
        effects = listOf(DocumentEffect.UploadFile(fileName, fileContent))
      )
    }
}

/**
 * Mark upload as completed and trigger virus scan.
 */
class UploadCompleted(
  private val fileId: String
) : DocumentTransition(from = DocumentState.Uploading, to = DocumentState.Scanning) {

  override fun decide(value: DocumentUpload): Decision<DocumentUpload, DocumentState, DocumentEffect> =
    Decision.accept(
      value = value.update(DocumentState.Scanning),
      effects = listOf(DocumentEffect.ScanFile(fileId))
    )
}

/**
 * Upload failed.
 */
class UploadFailed(
  private val reason: String
) : DocumentTransition(from = DocumentState.Uploading, to = DocumentState.Rejected(reason)) {

  override fun decide(value: DocumentUpload): Decision<DocumentUpload, DocumentState, DocumentEffect> =
    Decision.accept(
      value = value.update(DocumentState.Rejected(reason)),
      effects = listOf(DocumentEffect.NotifyUser(value.id, "Upload failed: $reason"))
    )
}

/**
 * Virus scan succeeded - document is accepted.
 */
class ScanSucceeded(
  private val report: ScanReport
) : DocumentTransition(from = DocumentState.Scanning, to = DocumentState.Accepted) {

  override fun decide(value: DocumentUpload): Decision<DocumentUpload, DocumentState, DocumentEffect> =
    Decision.accept(
      value = value.update(DocumentState.Accepted),
      effects = listOf(DocumentEffect.NotifyUser(value.id, "Document accepted"))
    )
}

/**
 * Virus scan failed - document is rejected.
 */
class ScanFailed(
  private val reason: String
) : DocumentTransition(from = DocumentState.Scanning, to = DocumentState.Rejected(reason)) {

  override fun decide(value: DocumentUpload): Decision<DocumentUpload, DocumentState, DocumentEffect> =
    Decision.accept(
      value = value.update(DocumentState.Rejected(reason)),
      effects = listOf(DocumentEffect.NotifyUser(value.id, "Document rejected: $reason"))
    )
}

package app.cash.kfsm.v2.exemplar

import app.cash.kfsm.v2.Effect
import app.cash.kfsm.v2.State
import app.cash.kfsm.v2.Value

/**
 * Value representing a document upload workflow.
 */
data class DocumentUpload(
  override val id: String,
  override val state: DocumentState,
  val fileName: String? = null,
  val fileId: String? = null,
  val scanReport: ScanReport? = null,
  val rejectionReason: String? = null
) : Value<String, DocumentUpload, DocumentState> {
  override fun update(newState: DocumentState): DocumentUpload = copy(state = newState)
}

data class ScanReport(val checksum: String, val virusFree: Boolean)

// --- States ---

sealed class DocumentState : State<DocumentState>() {
  data object Idle : DocumentState() {
    override fun transitions() = setOf(Uploading)
  }

  data object Uploading : DocumentState() {
    override fun transitions(): Set<DocumentState> = setOf(Scanning)
    override fun canTransitionTo(other: DocumentState) = 
      super.canTransitionTo(other) || other is Rejected
  }

  data object Scanning : DocumentState() {
    override fun transitions(): Set<DocumentState> = setOf(Accepted)
    override fun canTransitionTo(other: DocumentState) = 
      super.canTransitionTo(other) || other is Rejected
  }

  data object Accepted : DocumentState() {
    override fun transitions(): Set<DocumentState> = emptySet()
  }

  data class Rejected(val reason: String) : DocumentState() {
    override fun transitions(): Set<DocumentState> = emptySet()
  }
}

// --- Effects ---

sealed class DocumentEffect : Effect {
  data class UploadFile(val fileName: String, val content: ByteArray) : DocumentEffect()
  data class ScanFile(val fileId: String) : DocumentEffect()
  data class NotifyUser(val documentId: String, val status: String) : DocumentEffect()
}

package app.cash.kfsm.v2.exemplar

import app.cash.kfsm.v2.EffectHandler
import app.cash.kfsm.v2.EffectOutcome

/**
 * Executes effects and returns transitions to continue the workflow.
 *
 * In a real application, this would call external services (file storage, virus scanner, etc.).
 * For testing, we use pluggable lambdas to control the behavior.
 */
class DocumentUploadEffectHandler(
  private val uploadFile: (fileName: String, content: ByteArray) -> Result<String>,
  private val scanFile: (fileId: String) -> Result<ScanResult>,
  private val notifyUser: (documentId: String, status: String) -> Result<Unit>
) : EffectHandler<String, DocumentUpload, DocumentState, DocumentEffect> {

  sealed class ScanResult {
    data class Success(val report: ScanReport) : ScanResult()
    data class Failure(val reason: String) : ScanResult()
  }

  override fun handle(
    valueId: String,
    effect: DocumentEffect
  ): Result<EffectOutcome<String, DocumentUpload, DocumentState, DocumentEffect>> = when (effect) {
    is DocumentEffect.UploadFile ->
      uploadFile(effect.fileName, effect.content)
        .map { fileId ->
          EffectOutcome.TransitionProduced(valueId, UploadCompleted(fileId))
        }
        .recoverCatching { error ->
          EffectOutcome.TransitionProduced(valueId, UploadFailed(error.message ?: "Upload failed"))
        }

    is DocumentEffect.ScanFile ->
      scanFile(effect.fileId)
        .map { result ->
          val transition = when (result) {
            is ScanResult.Success -> ScanSucceeded(result.report)
            is ScanResult.Failure -> ScanFailed(result.reason)
          }
          EffectOutcome.TransitionProduced(valueId, transition)
        }

    is DocumentEffect.NotifyUser ->
      notifyUser(effect.documentId, effect.status)
        .map { EffectOutcome.Completed }
  }
}

package app.cash.kfsm.v2.testing

import app.cash.kfsm.v2.Effect
import app.cash.kfsm.v2.Outbox
import app.cash.kfsm.v2.OutboxMessage

/**
 * In-memory implementation of [Outbox] for testing.
 *
 * Example:
 * ```kotlin
 * val outbox = InMemoryOutbox<String, OrderEffect>()
 * val processor = EffectProcessor(outbox, handler, stateMachine, valueLoader)
 * ```
 */
class InMemoryOutbox<ID, Ef : Effect> : Outbox<ID, Ef> {
    private val messages = mutableListOf<OutboxMessage<ID, Ef>>()
    private val processed = mutableSetOf<String>()
    private val failed = mutableMapOf<String, String>()
    private val deadLetters = mutableSetOf<String>()

    /**
     * Add a message to the outbox (for testing setup).
     */
    fun add(message: OutboxMessage<ID, Ef>) {
        messages.add(message)
    }

    /**
     * Get all messages currently in the outbox.
     */
    fun all(): List<OutboxMessage<ID, Ef>> = messages.toList()

    /**
     * Get all processed message IDs.
     */
    fun processedIds(): Set<String> = processed.toSet()

    /**
     * Get all failed messages with their error messages.
     */
    fun failedMessages(): Map<String, String> = failed.toMap()

    /**
     * Clear all messages (for test reset).
     */
    fun clear() {
        messages.clear()
        processed.clear()
        failed.clear()
        deadLetters.clear()
    }

    override fun fetchPending(batchSize: Int, effectTypes: Set<String>?): Result<List<OutboxMessage<ID, Ef>>> =
        Result.success(
            messages
                .filter { it.id !in processed && it.id !in deadLetters }
                .filter { it.dependsOnEffectId == null || it.dependsOnEffectId in processed }
                .let { pending ->
                    if (effectTypes.isNullOrEmpty()) pending
                    else pending.filter { it.effect::class.simpleName in effectTypes }
                }
                .take(batchSize)
        )

    override fun isProcessed(id: String): Result<Boolean> = Result.success(id in processed)

    override fun findById(id: String): Result<OutboxMessage<ID, Ef>?> =
        Result.success(messages.find { it.id == id })

    override fun markProcessed(id: String): Result<Unit> {
        processed.add(id)
        return Result.success(Unit)
    }

    override fun markFailed(id: String, error: String, maxAttempts: Int?): Result<Unit> {
        failed[id] = error
        if (maxAttempts != null && (failed.count { it.key == id } >= maxAttempts)) {
            deadLetters.add(id)
        }
        return Result.success(Unit)
    }

    override fun markDeadLetter(id: String, error: String): Result<Unit> {
        deadLetters.add(id)
        failed[id] = error
        return Result.success(Unit)
    }

    override fun fetchDeadLetters(batchSize: Int, effectTypes: Set<String>?): Result<List<OutboxMessage<ID, Ef>>> =
        Result.success(
            messages
                .filter { it.id in deadLetters }
                .let { dead ->
                    if (effectTypes.isNullOrEmpty()) dead
                    else dead.filter { it.effect::class.simpleName in effectTypes }
                }
                .take(batchSize)
        )

    override fun retryDeadLetter(id: String): Result<Boolean> {
        if (id in deadLetters) {
            deadLetters.remove(id)
            failed.remove(id)
            return Result.success(true)
        }
        return Result.success(false)
    }
}

package app.cash.kfsm.v2.exemplar.document

import app.cash.kfsm.v2.PendingRequestStatus
import app.cash.kfsm.v2.PendingRequestStore
import java.util.UUID
import java.util.concurrent.ConcurrentHashMap

class InMemoryPendingRequestStore<ID, V> : PendingRequestStore<ID, V> {

  private data class Entry<V>(
    val valueId: Any,
    var status: PendingRequestStatus<V>
  )

  private val requests = ConcurrentHashMap<String, Entry<V>>()
  private val valueIdToRequestIds = ConcurrentHashMap<Any, MutableSet<String>>()

  override fun create(valueId: ID): Result<String> {
    val requestId = UUID.randomUUID().toString()
    requests[requestId] = Entry(valueId as Any, PendingRequestStatus.Waiting)
    valueIdToRequestIds.computeIfAbsent(valueId as Any) { mutableSetOf() }.add(requestId)
    return Result.success(requestId)
  }

  override fun getStatus(requestId: String): Result<PendingRequestStatus<V>> {
    return Result.success(requests[requestId]?.status ?: PendingRequestStatus.NotFound)
  }

  override fun complete(valueId: ID, value: V): Result<Unit> {
    val requestIds = valueIdToRequestIds[valueId as Any] ?: return Result.success(Unit)
    requestIds.forEach { requestId ->
      requests[requestId]?.let { entry ->
        if (entry.status is PendingRequestStatus.Waiting) {
          entry.status = PendingRequestStatus.Completed(value)
        }
      }
    }
    return Result.success(Unit)
  }

  override fun fail(valueId: ID, error: String): Result<Unit> {
    val requestIds = valueIdToRequestIds[valueId as Any] ?: return Result.success(Unit)
    requestIds.forEach { requestId ->
      requests[requestId]?.let { entry ->
        if (entry.status is PendingRequestStatus.Waiting) {
          entry.status = PendingRequestStatus.Failed(error)
        }
      }
    }
    return Result.success(Unit)
  }

  override fun timeout(requestId: String): Result<Unit> {
    requests[requestId]?.let { entry ->
      if (entry.status is PendingRequestStatus.Waiting) {
        entry.status = PendingRequestStatus.Failed("Timed out")
      }
    }
    return Result.success(Unit)
  }

  override fun delete(requestId: String): Result<Unit> {
    val entry = requests.remove(requestId)
    if (entry != null) {
      valueIdToRequestIds[entry.valueId]?.remove(requestId)
    }
    return Result.success(Unit)
  }

  fun clear() {
    requests.clear()
    valueIdToRequestIds.clear()
  }
}

package app.cash.kfsm.v2.exemplar.document.infra

import app.cash.kfsm.v2.exemplar.document.ScanReport
import java.time.Instant
import java.util.UUID
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.Executors
import java.util.concurrent.TimeUnit

/**
 * Mock virus scanner service that runs on a separate thread pool.
 *
 * Simulates an external virus scanning service with configurable behavior:
 * - Async scanning with configurable delay
 * - Ability to mark specific files as infected
 * - Callbacks when scans complete
 *
 * All operations return Result for functional error handling.
 */
class MockVirusScanner(
  private val scanDelayMs: Long = 500,
  private val onScanComplete: (ScanResult) -> Unit
) : AutoCloseable {

  private val executor = Executors.newSingleThreadExecutor { r ->
    Thread(r, "virus-scanner").apply { isDaemon = true }
  }

  private val infectedFiles = ConcurrentHashMap.newKeySet<String>()
  private val pendingScans = ConcurrentHashMap<String, ScanRequest>()

  data class ScanRequest(
    val documentId: String,
    val fileStorageId: String,
    val submittedAt: Instant = Instant.now()
  )

  sealed class ScanResult {
    abstract val documentId: String
    abstract val fileStorageId: String
    abstract val report: ScanReport

    data class Clean(
      override val documentId: String,
      override val fileStorageId: String,
      override val report: ScanReport
    ) : ScanResult()

    data class Infected(
      override val documentId: String,
      override val fileStorageId: String,
      override val report: ScanReport
    ) : ScanResult()

    data class Error(
      override val documentId: String,
      override val fileStorageId: String,
      override val report: ScanReport,
      val error: String
    ) : ScanResult()
  }

  /**
   * Submit a file for virus scanning. Returns immediately.
   * The scan runs asynchronously and calls [onScanComplete] when done.
   *
   * @return Success with scan ID, or failure if submission fails
   */
  fun submitScan(documentId: String, fileStorageId: String): Result<String> {
    val scanId = UUID.randomUUID().toString()
    val request = ScanRequest(documentId, fileStorageId)
    pendingScans[scanId] = request

    executor.submit {
      try {
        Thread.sleep(scanDelayMs)
        val result = performScan(request)
        pendingScans.remove(scanId)
        onScanComplete(result)
      } catch (e: InterruptedException) {
        Thread.currentThread().interrupt()
      } catch (e: Exception) {
        pendingScans.remove(scanId)
        onScanComplete(
          ScanResult.Error(
            documentId = request.documentId,
            fileStorageId = request.fileStorageId,
            report = ScanReport(
              scannedAt = Instant.now(),
              virusFree = false,
              checksum = "",
              threatName = null
            ),
            error = e.message ?: "Unknown error"
          )
        )
      }
    }

    return Result.success(scanId)
  }

  private fun performScan(request: ScanRequest): ScanResult {
    val isInfected = infectedFiles.contains(request.fileStorageId)
    val checksum = UUID.randomUUID().toString().replace("-", "").take(32)

    val report = ScanReport(
      scannedAt = Instant.now(),
      virusFree = !isInfected,
      checksum = checksum,
      threatName = if (isInfected) "EICAR-Test-File" else null
    )

    return if (isInfected) {
      ScanResult.Infected(request.documentId, request.fileStorageId, report)
    } else {
      ScanResult.Clean(request.documentId, request.fileStorageId, report)
    }
  }

  /**
   * Mark a file storage ID as infected for testing.
   */
  fun markAsInfected(fileStorageId: String) {
    infectedFiles.add(fileStorageId)
  }

  /**
   * Clear the infected files list.
   */
  fun clearInfectedFiles() {
    infectedFiles.clear()
  }

  fun pendingScanCount(): Int = pendingScans.size

  override fun close() {
    executor.shutdown()
    executor.awaitTermination(5, TimeUnit.SECONDS)
  }
}

